1084 | async function loadStatistics(updateEntryCards = true) {
1085 | 	let timeValue = statTimeSelect.value;
1086 | 	let rec = await getRecords();
1087 | 	if (!(timeValue === "all")) {
1088 | 		if (parseInt(timeValue) === 0) {
1089 | 			// Today
1090 | 			// Get the current date without the time component
1091 | 			const currentDate = new Date();
1092 | 			currentDate.setHours(0, 0, 0, 0);
1093 | 
1094 | 			// Calculate the start and end timestamps for the current day
1095 | 			const startOfDay = currentDate.getTime();
1096 | 			const endOfDay = startOfDay + 24 * 60 * 60 * 1000;
1097 | 
1098 | 			rec = rec.filter((r) => {
1099 | 				// Check if the task is within the current day
1100 | 				return r.d >= startOfDay && r.d < endOfDay && filteredTasks.has(r.n);
1101 | 			});
1102 | 		} else {
1103 | 			let tt = Date.now() - parseInt(timeValue) * 24 * 60 * 60 * 1000;
1104 | 			rec = rec.filter((r) => r.d >= tt && filteredTasks.has(r.n));
1105 | 		}
1106 | 	}
1107 | 	let charts = [];
1108 | 	let maxvalue = 0;
1109 | 	let minRoundValue = 0;
1110 | 	let maxRoundValue = 0;
1111 | 	let totalValue = 0;
1112 | 	let hourlyTimes = new Array(4).fill(0);
1113 | 	let dayTimes = new Array(7).fill(0);
1114 | 	let monthTimes = new Array(12).fill(0);
1115 | 	for (let task of filteredTasks) {
1116 | 		let chart = {
1117 | 			t: 0,
1118 | 			task: task,
1119 | 			n: 0,
1120 | 		};
1121 | 		rec.filter((r) => r.n === task).forEach((r) => {
1122 | 			chart.t += r.t;
1123 | 			totalValue += r.t;
1124 | 			let d = new Date(r.d);
1125 | 			hourlyTimes[Math.floor(d.getHours() / 6)] += r.t;
1126 | 			dayTimes[d.getDay()] += r.t;
1127 | 			monthTimes[d.getMonth()] += r.t;
1128 | 			chart.n++;
1129 | 			if (minRoundValue === 0) {
1130 | 				minRoundValue = r.t;
1131 | 			} else {
1132 | 				minRoundValue = minRoundValue > r.t ? r.t : minRoundValue;
1133 | 			}
1134 | 			maxRoundValue = maxRoundValue < r.t ? r.t : maxRoundValue;
1135 | 		});
1136 | 		maxvalue = maxvalue < chart.t ? chart.t : maxvalue;
1137 | 
1138 | 		charts.push(chart);
1139 | 	}
1140 | 	statSummaryTotal.innerText = hmstrFull(totalValue);
1141 | 	statSummaryRounds.innerText = rec.length;
1142 | 	statSummaryAverage.innerText = hmstrFull(totalValue / (rec.length === 0 ? 1 : rec.length));
1143 | 	statSummaryShortest.innerText = hmstrFull(minRoundValue);
1144 | 	statSummaryLongest.innerText = hmstrFull(maxRoundValue);
1145 | 
1146 | 	if (totalValue === 0) {
1147 | 		remarkDaily.style.display = remarkHourly.style.display = remarkMonthly.style.display = "none";
1148 | 	} else {
1149 | 		remarkDaily.style.display = remarkHourly.style.display = remarkMonthly.style.display = "block";
1150 | 		let maxH = 1;
1151 | 		let maxHV = 0;
1152 | 		hourlyTimes.forEach((v, i) => {
1153 | 			if (v > maxHV) {
1154 | 				maxHV = v;
1155 | 				maxH = i;
1156 | 			}
1157 | 		});
1158 | 		remarkHourly.querySelector(".remark-value").innerText = hourlyFullNames[maxH];
1159 | 
1160 | 		let maxD = 1;
1161 | 		let maxDV = 0;
1162 | 		dayTimes.forEach((v, i) => {
